// Stop with a plain message if the Config node still has placeholders or a setting is in the wrong format
const c = $('Config').first().json;
const text = (v) => String(v == null ? '' : v).trim();
const isPlaceholder = (v) => !text(v) || /PLACEHOLDER|REPLACE_WITH/i.test(text(v));
const missing = [];

if (isPlaceholder(c.workspaceId) || !/^\d+$/.test(text(c.workspaceId))) {
  missing.push('workspaceId (the number after app.clickup.com/ in your browser)');
}
if (text(c.listIds) && !/^\d+(\s*,\s*\d+)*$/.test(text(c.listIds))) {
  missing.push('listIds (list IDs separated by commas, or leave it empty for every list)');
}
for (const key of ['reviewStatus', 'approvedStatus', 'changesStatus', 'clientEmailField', 'reviewLinkField', 'clientNameField', 'yourName', 'businessName']) {
  if (isPlaceholder(c[key])) missing.push(key);
}
if (isPlaceholder(c.slackChannelId) || !/^[CDGUW][A-Z0-9]{8,}$/.test(text(c.slackChannelId))) {
  missing.push('slackChannelId (an ID like C0123ABCD, not the channel name)');
}
if (!['draft', 'send'].includes(text(c.sendMode).toLowerCase())) {
  missing.push('sendMode (draft to check each review email in Gmail before it goes, or send to send it straight away)');
}
const days = Number(c.reminderDays);
if (!Number.isFinite(days) || days < 1) missing.push('reminderDays (a number, 1 or more)');
if (!text(c.approvalPhrases).split(',').some((p) => p.trim())) missing.push('approvalPhrases (words that count as a clear approval, separated by commas)');
if (isPlaceholder(c.waitingTag) || text(c.waitingTag).length > 50) missing.push('waitingTag (a short tag name, such as awaiting client reply)');
if ([c.approvedStatus, c.changesStatus].some((s) => text(s).toLowerCase() === text(c.reviewStatus).toLowerCase())) {
  missing.push('approvedStatus and changesStatus (they must be different from reviewStatus)');
}

if (missing.length) {
  throw new Error('Open the Config node and fill in: ' + missing.join(', '));
}

// Two ClickUp searches: tasks waiting in the review status, and tasks that still carry the waiting tag
const lists = text(c.listIds).split(',').map((s) => s.trim()).filter(Boolean).map((id) => '&list_ids[]=' + id).join('');
const base = 'https://api.clickup.com/api/v2/team/' + text(c.workspaceId) + '/task?subtasks=true';
return [{
  json: {
    tasksUrl: base + '&include_closed=false&statuses[]=' + encodeURIComponent(text(c.reviewStatus).toLowerCase()) + lists,
    taggedUrl: base + '&include_closed=true&tags[]=' + encodeURIComponent(text(c.waitingTag).toLowerCase()) + lists
  }
}];

// Turn every page of ClickUp's task search into one item per task, with the client's email, name, the review link and whether it carries the waiting tag
const cfg = $('Config').first().json;
const pages = $input.all().map((i) => i.json || {});
const failed = pages.find((p) => p.err || p.ECODE);
if (failed) {
  throw new Error('ClickUp said: ' + (failed.err || failed.ECODE) + '. Check workspaceId in Config and your ClickUp credential.');
}
const text = (v) => String(v == null ? '' : v).trim();
const lower = (v) => text(v).toLowerCase();
const tag = lower(cfg.waitingTag);
const seen = new Set();
const tasks = pages.flatMap((p) => (Array.isArray(p.tasks) ? p.tasks : [])).filter((t) => t && t.id && !seen.has(t.id) && seen.add(t.id));

// A detail can be a custom field on the task, or a line in the description such as "Client Email: user@example.com"
function fromField(task, name) {
  const f = (task.custom_fields || []).find((c) => lower(c.name) === lower(name));
  if (!f || f.value == null || f.value === '') return '';
  const options = (f.type_config && f.type_config.options) || [];
  // Dropdown and label fields store an option ID or position, so look up the option's name
  if (f.type === 'drop_down') {
    const o = options.find((x) => x.id === f.value || (x.orderindex != null && String(x.orderindex) === String(f.value)));
    return o ? text(o.name || o.label) : '';
  }
  if (f.type === 'labels' && Array.isArray(f.value)) {
    return f.value.map((id) => { const o = options.find((x) => x.id === id); return o ? text(o.label || o.name) : ''; }).filter(Boolean).join(', ');
  }
  if (Array.isArray(f.value)) return f.value.map((v) => (v && typeof v === 'object' ? text(v.email || v.username || v.name) : text(v))).filter(Boolean).join(', ');
  if (typeof f.value === 'object') return text(f.value.url || f.value.email || f.value.value || f.value.name || '');
  return text(f.value);
}
function fromDescription(task, label) {
  const body = String(task.text_content || task.description || '');
  const safe = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const m = body.match(new RegExp('^\\s*' + safe + '\\s*:\\s*(.+)$', 'im'));
  return m ? m[1].trim() : '';
}

return tasks.map((t) => {
  const emailText = fromField(t, cfg.clientEmailField) || fromDescription(t, cfg.clientEmailField);
  const clientEmails = [...new Set((emailText.match(/[^\s,;<>()"]+@[^\s,;<>()"]+\.[a-z]{2,}/gi) || []).map((e) => e.toLowerCase()))];
  const linkText = fromField(t, cfg.reviewLinkField) || fromDescription(t, cfg.reviewLinkField);
  const reviewLink = (linkText.match(/https?:\/\/[^\s<>"]+/i) || [''])[0];
  const clientName = fromField(t, cfg.clientNameField) || fromDescription(t, cfg.clientNameField);
  return {
    json: {
      taskId: t.id,
      taskName: text(t.name) || 'Untitled task',
      taskUrl: t.url || 'https://app.clickup.com/t/' + t.id,
      listName: (t.list && t.list.name) || '',
      clientEmails,
      clientName,
      reviewLink,
      hasTag: (t.tags || []).some((g) => lower(g && g.name) === tag)
    }
  };
});

// Read this workflow's notes and the waiting tag on each task to decide: send the review email, report a problem, or watch for the client's reply
const cfg = $('Config').first().json;
const morning = $('Every Morning at 9').isExecuted;
const tasks = $('List Review Tasks').all().map((i) => i.json);
const notesByTask = {};
$input.all().forEach((i) => { if (i.json && i.json.taskId) notesByTask[i.json.taskId] = i.json.comments || []; });
const MARK = /\(n8n review: ([^)]*)\)/g;
const tag = String(cfg.waitingTag || '').trim().toLowerCase();
const draftMode = String(cfg.sendMode || '').trim().toLowerCase() !== 'send';
const slackSafe = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = (s) => String(s || '').toLowerCase().replace(/[‘’ʼ`']/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const now = Date.now();
const today = $now.toFormat('d LLL, HH:mm');
const out = [];

for (const task of tasks) {
  const notes = (notesByTask[task.taskId] || [])
    .map((c) => ({ text: String(c.comment_text || ''), date: Number(c.date) || 0 }))
    .sort((a, b) => b.date - a.date);
  // Our marker is always the last thing in our own notes, so read the last one in each note
  const markerOf = (t) => { const all = [...t.matchAll(MARK)]; return all.length ? all[all.length - 1][1] : null; };

  // 1. Walk back from the newest note to the start of the current review round
  let last = '';
  let sent = null;
  let bouncedTo = [];
  const processedIds = [];
  const alertedIds = [];
  for (const c of notes) {
    const m = markerOf(c.text);
    if (m == null) continue;
    const parts = m.split(',').map((s) => s.trim());
    const words = parts[0].split(/\s+/);
    if (words[0] === 'reply') {
      if (parts[1] === 'approved' || parts[1] === 'changes') { last = 'closed'; break; } // the client decided, so that round is over
      words.slice(1).forEach((id) => processedIds.push(id));
    } else if (words[0] === 'other') {
      words.slice(1).forEach((id) => alertedIds.push(id));
    } else if (words[0] === 'sent') {
      const pick = (label) => ((parts.find((p) => p.startsWith(label + ' ')) || '').slice(label.length + 1));
      sent = { threadId: pick('thread'), emailId: pick('email'), date: c.date };
      last = sent.threadId && sent.threadId !== 'undefined' ? 'sent' : 'closed';
      break;
    } else if (words[0] === 'bounced') {
      bouncedTo = (parts.find((p) => p.startsWith('to ')) || '').slice(3).split(/\s+/).filter(Boolean).map((e) => e.toLowerCase());
      last = 'bounced';
      break;
    } else if (words[0] === 'blocked' || words[0] === 'stuck') {
      last = words[0];
      break;
    }
  }
  // Safety limit: never email the same task more than 3 times in 24 hours, whatever else goes wrong
  const recentSends = notes.filter((c) => (markerOf(c.text) || '').startsWith('sent') && now - c.date < 86400000).length;

  // 2. Decide. The waiting tag is added before the email goes out, so a tag without a "sent" note means the last send may have failed half way.
  const missing = [];
  if (!task.clientEmails.length) missing.push('the client\'s email');
  if (!task.reviewLink) missing.push('the review link');
  let step;
  if (last === 'sent') step = task.hasTag ? 'watch' : 'new'; // no tag: the task left review and came back, or someone removed the tag to send again
  else if (last === 'stuck') step = task.hasTag || recentSends >= 3 ? 'skip' : 'new';
  else if (last === 'bounced') step = task.clientEmails.length && task.clientEmails.every((e) => bouncedTo.includes(e)) ? 'skip' : 'new';
  else if (last === 'blocked') step = missing.length ? 'skip' : 'new';
  else if (last === '' && task.hasTag) step = 'stuck';
  else step = 'new';
  if (step === 'new') step = missing.length ? 'block' : recentSends >= 3 ? 'limit' : 'send';
  if (step === 'skip' || (morning && step !== 'watch')) continue; // the morning run only reads replies, so it can never email a client twice

  const firstName = String(task.clientName || '').trim().split(/\s+/)[0] || 'there';
  const taskLink = '<' + task.taskUrl + '|' + slackSafe(task.taskName) + '>';
  const to = task.clientEmails.join(', ');
  const item = { ...task, action: step === 'watch' ? 'watch' : step === 'send' ? 'send' : 'note', firstName };

  if (step === 'watch') {
    Object.assign(item, {
      threadId: sent.threadId,
      requestEmailId: sent.emailId,
      sentAt: sent.date,
      processedIds,
      alertedIds,
      // The start of each line this workflow writes, so quoted copies of our own emails can be cut out of replies
      ownLines: [norm(task.taskName + ' is ready for your review'), 'if you are happy with it just reply approved',
        norm('I wanted to check in on ' + task.taskName), 'reply approved if you are happy with it']
    });
  } else if (step === 'send') {
    Object.assign(item, {
      emailSubject: 'Ready for your review: ' + task.taskName,
      emailBody: 'Hi ' + firstName + ',\n\n' + task.taskName + ' is ready for your review:\n' + task.reviewLink +
        '\n\nIf you are happy with it, just reply "approved". If you would like changes, reply with what you would like changed and we will get on it.\n\n' +
        cfg.yourName + '\n' + cfg.businessName,
      sentNote: draftMode
        ? '📝 The review email to ' + to + ' was saved as a Gmail draft on ' + today + '. It goes to the client when you press Send in Gmail, and their reply will update this task.'
        : '📨 Sent to ' + to + ' for review on ' + today + '. Waiting for their reply.',
      slackSent: draftMode
        ? ':memo: The review email for ' + taskLink + ' is ready in your Gmail drafts, addressed to ' + slackSafe(to) + '. Check the address and link, then press Send. Their reply will update the task.'
        : ':outbox_tray: Sent ' + taskLink + ' to ' + slackSafe(to) + ' for review. Their reply will update the task.',
      // Used only if Gmail refuses the email
      noteComment: '⚠️ The review email could not be ' + (draftMode ? 'saved as a Gmail draft' : 'sent') + ' (Gmail said: {error}). Check the client\'s email on this task, then remove the "' +
        tag + '" tag to try again. (n8n review: stuck)',
      noteSlack: ':warning: The review email for ' + taskLink + ' could not be ' + (draftMode ? 'saved as a draft' : 'sent') + '. Check the client\'s email on the task, then remove the "' + slackSafe(tag) + '" tag to try again.'
    });
  } else if (step === 'block') {
    Object.assign(item, {
      noteComment: '⚠️ The review email was not sent. Add ' + missing.join(' and ') + ' to this task, either as a custom field or as a line in the description such as "' +
        cfg.clientEmailField + ': name@company.com" or "' + cfg.reviewLinkField + ': https://...". It will go out on the next check. (n8n review: blocked)',
      noteSlack: ':warning: ' + taskLink + ' is in ' + slackSafe(cfg.reviewStatus) + ', but the review email was not sent: add ' + missing.join(' and ') + ' to the task.'
    });
  } else if (step === 'limit') {
    Object.assign(item, {
      noteComment: '⛔ This task has already been emailed to the client 3 times in the last 24 hours, so the workflow stopped to avoid emailing them again. ' +
        'Check the task and your Gmail Sent folder. It can send again after 24 hours. (n8n review: stuck)',
      noteSlack: ':no_entry: ' + taskLink + ' was emailed to the client 3 times in 24 hours, so the workflow stopped sending for it. Please check the task and Gmail.'
    });
  } else {
    Object.assign(item, {
      noteComment: '⚠️ This task has the "' + tag + '" tag, but there is no record of a review email for this round. Nothing was sent, so the client is not emailed twice. ' +
        'Check your Gmail Sent folder and drafts. To send the review email, remove the tag. (n8n review: stuck)',
      noteSlack: ':warning: ' + taskLink + ' has the "' + slackSafe(tag) + '" tag but no record of a review email, so nothing was sent. Check Gmail, then remove the tag to send it.'
    });
  }
  out.push({ json: item });
}
return out;

// Put every page of this task's comments together, so the review state is worked out from the full history
const task = $('Loop Over Review Tasks').first().json;
const pages = $input.all().map((i) => i.json || {});
const failed = pages.find((p) => p.err || p.ECODE);
if (failed) {
  throw new Error('ClickUp would not return the comments on "' + task.taskName + '": ' + (failed.err || failed.ECODE) + '. Check your ClickUp credential.');
}
const comments = pages.flatMap((p) => (Array.isArray(p.comments) ? p.comments : []));
return [{ json: { taskId: task.taskId, comments } }];

// Every morning: find review emails still sitting in drafts, clients who have not answered, and replies your team has not answered yet
const cfg = $('Config').first().json;
const watched = {};
$('Work Out Review State').all().forEach((i) => { if (i.json.action === 'watch') watched[i.json.threadId] = i.json; });
function header(m, name) {
  const want = name.toLowerCase();
  const key = Object.keys(m).find((k) => k.toLowerCase() === want && typeof m[k] === 'string');
  if (key) return m[key];
  const h = ((m.payload && m.payload.headers) || []).find((x) => String(x.name || '').toLowerCase() === want);
  return h ? String(h.value || '') : '';
}
const addressOf = (m) => {
  const v = m.from && m.from.value && m.from.value[0] && m.from.value[0].address;
  const found = String(v || header(m, 'From')).match(/[^\s<>"]+@[^\s<>"]+/);
  return found ? found[0].toLowerCase() : '';
};
const timeOf = (m) => Number(m.internalDate) || Date.parse(m.date || header(m, 'Date') || '') || 0;
const labelsOf = (m) => (m.labelIds || []).concat((m.labels || []).map((l) => (l && (l.id || l)) || ''));
const isDraft = (m) => labelsOf(m).includes('DRAFT');
const subjectOf = (m) => String(m.subject || header(m, 'Subject'));
// Drafts, bounce notices and automatic replies (out of office) do not count as anyone answering
const ignore = (m) => isDraft(m) || /mailer-daemon|postmaster/i.test(addressOf(m)) ||
  (header(m, 'Auto-Submitted') && header(m, 'Auto-Submitted').toLowerCase() !== 'no') || !!header(m, 'X-Autoreply') ||
  /^(automatic reply|auto[- ]?reply|autoreply|out of (the )?office)/i.test(subjectOf(m));
const zone = $now.zoneName;
const today = $now.startOf('day');
const every = Math.max(1, Number(cfg.reminderDays) || 3);
const daysSince = (ms) => Math.floor(today.diff(DateTime.fromMillis(ms, { zone }).startOf('day'), 'days').days);

const out = [];
for (const item of $input.all()) {
  const thread = item.json || {};
  const task = watched[thread.id];
  if (!task) continue;
  const all = Array.isArray(thread.messages) ? thread.messages : [];
  const drafts = all.filter(isDraft);
  const msgs = all.filter((m) => !ignore(m)).sort((a, b) => timeOf(a) - timeOf(b));
  // The review email was saved as a draft and nobody has pressed Send yet
  if (!msgs.length) {
    if (drafts.length) out.push({ json: { ...task, kind: 'unsent', days: daysSince(Math.min(...drafts.map(timeOf))) } });
    continue;
  }
  const last = msgs[msgs.length - 1];
  const days = daysSince(timeOf(last));
  const fromThem = last.id !== msgs[0].id && (task.clientEmails.includes(addressOf(last)) || !labelsOf(last).includes('SENT'));
  const first = msgs[0];
  const subject = subjectOf(first).replace(/^(re:\s*)+/i, '') || 'Ready for your review: ' + task.taskName;
  const base = { ...task, days, lastThreadAt: timeOf(last), hasDraft: drafts.length > 0 };
  if (fromThem && days >= 1) {
    out.push({ json: { ...base, kind: 'unanswered' } });
  } else if (!fromThem && days >= every) {
    const sentOn = DateTime.fromMillis(timeOf(first), { zone }).toFormat('d LLLL');
    const draftBody = 'Hi ' + task.firstName + ',\n\nI wanted to check in on ' + task.taskName + ', which I sent over on ' + sentOn + '. Here is the link again:\n' + task.reviewLink +
      '\n\nReply "approved" if you are happy with it, or let me know what you would like changed.\n\n' + cfg.yourName + '\n' + cfg.businessName;
    // A reminder draft every few days, never a second one while an unsent draft is already waiting in this thread
    const due = days % every === 0 && !drafts.length;
    out.push({ json: { ...base, kind: due ? 'nudge' : 'waiting', subject: 'Re: ' + subject, draftBody } });
  }
}
return out;

// Sort the new messages in each review thread: client replies go to Claude; bounces, automatic replies and messages from other people never do
const cfg = $('Config').first().json;
const watchList = $('Work Out Review State').all().map((i) => i.json).filter((j) => j.action === 'watch');
const watched = {};
watchList.forEach((j) => { watched[j.threadId] = j; });
const tag = String(cfg.waitingTag || '').trim().toLowerCase();

const norm = (s) => String(s || '').toLowerCase().replace(/[‘’ʼ`']/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const slackSafe = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// n8n puts each email header on the message itself (From, Subject, Auto-Submitted and so on)
function header(m, name) {
  const want = name.toLowerCase();
  const key = Object.keys(m).find((k) => k.toLowerCase() === want && typeof m[k] === 'string');
  if (key) return m[key];
  const h = ((m.payload && m.payload.headers) || []).find((x) => String(x.name || '').toLowerCase() === want);
  return h ? String(h.value || '') : '';
}
const addressOf = (m) => {
  const v = m.from && m.from.value && m.from.value[0] && m.from.value[0].address;
  const found = String(v || header(m, 'From')).match(/[^\s<>"]+@[^\s<>"]+/);
  return found ? found[0].toLowerCase() : '';
};
const nameOf = (m) => String(header(m, 'From')).replace(/<[^>]*>/g, '').replace(/"/g, '').trim() || addressOf(m);
const timeOf = (m) => Number(m.internalDate) || Date.parse(m.date || header(m, 'Date') || '') || 0;
const labelsOf = (m) => (m.labelIds || []).concat((m.labels || []).map((l) => (l && (l.id || l)) || ''));
const isDraft = (m) => labelsOf(m).includes('DRAFT');
const isSent = (m) => labelsOf(m).includes('SENT');
const subjectOf = (m) => String(m.subject || header(m, 'Subject'));
// Bounce notices come from the mail system, not from a person
const isBounce = (m) => /mailer-daemon|postmaster/i.test(addressOf(m)) ||
  (/^(delivery status notification|undeliver|mail delivery (failed|failure|subsystem)|returned mail|delivery failure)/i.test(subjectOf(m)) && !!header(m, 'X-Failed-Recipients'));
// Out of office and other automatic replies are never treated as an answer
const isAuto = (m) => {
  const auto = header(m, 'Auto-Submitted').toLowerCase();
  if (auto && auto !== 'no') return true;
  if (header(m, 'X-Autoreply') || header(m, 'X-Autorespond')) return true;
  if (/auto_reply|auto-reply/i.test(header(m, 'Precedence'))) return true;
  return /^(automatic reply|auto[- ]?reply|autoreply|out of (the )?office|abwesenheitsnotiz|réponse automatique|respuesta automática|risposta automatica|automatisch antwoord)/i.test(subjectOf(m));
};

const decode = (s) => String(s || '').replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"')
  .replace(/&#(\d+);/g, (x, n) => String.fromCharCode(Number(n))).replace(/&#x([0-9a-f]+);/gi, (x, n) => String.fromCharCode(parseInt(n, 16))).replace(/&amp;/gi, '&');
// Some email apps send only an HTML version: drop the quoted older email, then turn the rest into plain text
function htmlToText(html) {
  let h = String(html || '');
  const quote = h.search(/<div[^>]*class="[^"]*gmail_(quote|extra)|<blockquote|<div[^>]*id="(appendonsend|divRplyFwdMsg|mail-editor-reference-message-container)"/i);
  if (quote >= 0) h = h.slice(0, quote); // a reply that is only the quoted email has no new text
  h = h.replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(div|p|li|tr|h[1-6])>/gi, '\n').replace(/<[^>]+>/g, '');
  return decode(h);
}
function bodyOf(m) {
  if (m.text) return String(m.text);
  const plain = [];
  const html = [];
  const walk = (p) => {
    if (!p) return;
    const data = p.body && p.body.data ? Buffer.from(p.body.data, 'base64').toString('utf8') : '';
    if (data && p.mimeType === 'text/plain') plain.push(data);
    if (data && p.mimeType === 'text/html') html.push(data);
    (p.parts || []).forEach(walk);
  };
  walk(m.payload);
  if (plain.length) return plain.join('\n');
  if (html.length) return html.map(htmlToText).join('\n');
  if (m.html) return htmlToText(m.html);
  return decode(m.snippet);
}
// Keep only what the client wrote this time: cut the quoted older emails (English and other languages) and any copy of our own email
function newPart(body, ownLines) {
  let t = String(body || '').replace(/\r\n/g, '\n');
  const cuts = [
    /^(On|Le|Am|El|Il|Op|Em|Den|På|W dniu|Dne)\s[\s\S]{3,300}?(wrote|a écrit|schrieb|escribió|ha scritto|schreef|escreveu|skrev|napisał|napsal|kirjoitti)[^\n]{0,150}:\s*$/im,
    /^-{2,}\s*(Original Message|Ursprüngliche Nachricht|Message d'origine|Mensaje original|Messaggio originale|Oorspronkelijk bericht|Forwarded message)\s*-{2,}/im,
    /^(From|Von|De|Van|Da|Fra|Från|Od)\s*:\s.+\n(Sent|Gesendet|Envoyé|Enviado|Verzonden|Inviato|Sendt|Skickat|Wysłano|Date|Datum|Fecha|Data)\s*:/im,
    /^_{5,}\s*$/m
  ];
  for (const re of cuts) {
    const m = t.match(re);
    if (m) t = t.slice(0, m.index); // a reply that starts with the quote header has no new text
  }
  const lines = t.split('\n');
  const own = (ownLines || []).filter((o) => o && o.length > 10);
  const at = lines.findIndex((l) => { const n = norm(l.replace(/^\s*>+/, '')); return own.some((o) => n.startsWith(o)); });
  const kept = (at >= 0 ? lines.slice(0, at) : lines).filter((l) => !/^\s*>/.test(l));
  while (kept.length && (!kept[kept.length - 1].trim() || /^\s*(hi|hello|hey|dear)\b[^.!?]{0,40},?\s*$/i.test(kept[kept.length - 1]))) kept.pop();
  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

const out = [];
$input.all().forEach((item, i) => {
  const thread = item.json || {};
  let task = watched[thread.id];
  if (!task) {
    // Gmail no longer has the thread (for example the review draft was deleted): say so once, instead of watching it forever
    const err = String((thread.error && (thread.error.message || thread.error)) || '');
    const pos = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : i;
    task = watchList[pos];
    if (task && /could not be found|not found|404/i.test(err)) {
      out.push({ json: {
        kind: 'notice', taskId: task.taskId,
        noteComment: '⚠️ The review email for this task is no longer in Gmail (it may have been deleted), so the workflow has stopped watching for a reply. ' +
          'To send a fresh review email, remove the "' + tag + '" tag from this task. (n8n review: stuck)',
        noteSlack: ':warning: The review email for <' + task.taskUrl + '|' + slackSafe(task.taskName) + '> is no longer in Gmail, so nothing is watching for a reply. Remove the "' + slackSafe(tag) + '" tag to send a fresh one.'
      } });
    }
    return; // any other Gmail error: try again on the next check
  }
  const mailLink = '<https://mail.google.com/mail/u/0/#all/' + task.threadId + '|Open the email>';
  const taskLink = '<' + task.taskUrl + '|' + slackSafe(task.taskName) + '>';
  const all = (Array.isArray(thread.messages) ? thread.messages : []).filter((m) => !isDraft(m)).sort((a, b) => timeOf(a) - timeOf(b));
  // The first message is always our own review email (its ID changes when a draft is sent from Gmail)
  const firstId = all.length ? all[0].id : '';
  const fresh = all
    .filter((m) => m.id !== task.requestEmailId && m.id !== firstId && timeOf(m) >= task.sentAt - 60000 && !task.processedIds.includes(m.id));
  const replies = [];
  const bounces = [];
  const others = [];
  for (const m of fresh) {
    const from = addressOf(m);
    if (isBounce(m)) { if (!task.alertedIds.includes(m.id)) bounces.push(m); continue; }
    if (isAuto(m)) continue;
    if (task.clientEmails.includes(from)) { replies.push(m); continue; }
    if (isSent(m)) continue; // your own messages in the thread
    if (!task.alertedIds.includes(m.id)) others.push(m);
  }

  // 1. The review email bounced: say so, and stop waiting if no client got it
  if (bounces.length) {
    const failedTo = new Set();
    bounces.forEach((m) => {
      const listed = header(m, 'X-Failed-Recipients').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
      const text = (bodyOf(m) + ' ' + String(m.snippet || '')).toLowerCase();
      (listed.length ? listed : task.clientEmails.filter((e) => text.includes(e))).forEach((e) => failedTo.add(e));
    });
    const failed = failedTo.size ? task.clientEmails.filter((e) => failedTo.has(e)) : task.clientEmails;
    const reached = task.clientEmails.filter((e) => !failed.includes(e));
    const ids = bounces.map((m) => m.id).join(' ');
    out.push({ json: reached.length ? {
      kind: 'notice', taskId: task.taskId,
      noteComment: '⚠️ The review email could not be delivered to ' + failed.join(', ') + '. It did reach ' + reached.join(', ') + ', so the workflow keeps waiting for their reply. (n8n review: other ' + ids + ')',
      noteSlack: ':warning: The review email for ' + taskLink + ' could not reach ' + slackSafe(failed.join(', ')) + '. It did reach ' + slackSafe(reached.join(', ')) + '. ' + mailLink
    } : {
      kind: 'notice', taskId: task.taskId,
      noteComment: '⛔ The review email could not be delivered to ' + failed.join(', ') + '. Fix the client\'s email on this task and the review email will go out again on the next check. (n8n review: bounced, to ' + task.clientEmails.join(' ') + ')',
      noteSlack: ':no_entry: The review email for ' + taskLink + ' bounced (' + slackSafe(failed.join(', ')) + '). Fix the client\'s email on the task and it will be sent again. ' + mailLink
    } });
    if (!reached.length) return;
  }

  // 2. Someone who is not on the task's client list replied: never act on it, just tell the team
  if (others.length) {
    const who = [...new Set(others.map((m) => nameOf(m) + (nameOf(m).includes('@') ? '' : ' (' + addressOf(m) + ')')))].join(', ');
    out.push({ json: {
      kind: 'notice', taskId: task.taskId,
      noteComment: '👤 ' + who + ' replied by email, but is not on this task\'s client list, so nothing was changed. If they can approve the work, add their email to the task and their reply will be read on the next check. (n8n review: other ' + others.map((m) => m.id).join(' ') + ')',
      noteSlack: ':bust_in_silhouette: *' + slackSafe(who) + '* replied about ' + taskLink + ', but is not on the task\'s client list, so nothing was changed. Add their email to the task if they can approve. ' + mailLink
    } });
  }

  // 3. The client's own replies, without quoted older emails
  if (!replies.length) return;
  const replyText = replies.map((m) => newPart(bodyOf(m), task.ownLines)).filter(Boolean).join('\n\n');
  const ids = replies.map((m) => m.id).join(' ');
  if (!replyText) {
    out.push({ json: {
      kind: 'notice', taskId: task.taskId,
      noteComment: '📎 The client replied without any text the workflow could read (it may be an attachment or an image). Nothing was changed. Read it in Gmail. (n8n review: reply ' + ids + ', empty)',
      noteSlack: ':paperclip: ' + slackSafe(task.clientName || task.clientEmails.join(', ')) + ' replied about ' + taskLink + ' without any readable text, so nothing was changed. ' + mailLink
    } });
    return;
  }
  out.push({ json: { ...task, kind: 'reply', replyIds: replies.map((m) => m.id), replyText: replyText.slice(0, 8000), replyAt: timeOf(replies[replies.length - 1]) } });
});
return out;

// Before drafting a reminder, check whether the client already emailed you in a different thread since the last message
const quiet = $('Find Quiet Clients').all().map((i) => i.json);
const mails = $input.all().map((i) => i.json || {}).filter((m) => m.id && m.threadId);
const addressOf = (m) => {
  const found = String(m.From || m.from || '').match(/[^\s<>"]+@[^\s<>"]+/);
  return found ? found[0].toLowerCase() : '';
};
return quiet.map((t) => {
  if (t.kind === 'unanswered' || t.kind === 'unsent') return { json: t };
  const other = mails
    .filter((m) => m.threadId !== t.threadId && t.clientEmails.includes(addressOf(m)) && Number(m.internalDate) > Number(t.lastThreadAt))
    .sort((a, b) => Number(b.internalDate) - Number(a.internalDate))[0];
  if (!other) return { json: t };
  const on = DateTime.fromMillis(Number(other.internalDate), { zone: $now.zoneName }).toFormat('d LLL');
  return { json: { ...t, kind: 'elsewhere', elsewhereOn: on, elsewhereSubject: String(other.Subject || other.subject || '(no subject)'), elsewhereThreadId: other.threadId } };
});

// One Slack message each morning with every review that is waiting on someone
const items = $input.all().map((i) => i.json);
const slackSafe = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = (t) => '<' + t.taskUrl + '|' + slackSafe(t.taskName) + '>';
const who = (t) => slackSafe(t.clientName || t.clientEmails.join(', '));
const plural = (n) => n + (n === 1 ? ' day' : ' days');

const lines = ['*Client reviews this morning*'];
const unsent = items.filter((t) => t.kind === 'unsent');
if (unsent.length) {
  lines.push('', ':memo: *Review emails still in your Gmail drafts*');
  unsent.forEach((t) => lines.push('• ' + link(t) + ': to ' + slackSafe(t.clientEmails.join(', ')) + ', drafted ' + (t.days ? plural(t.days) + ' ago' : 'today') + '. Open Gmail drafts, check it and press Send.'));
}
const nudges = items.filter((t) => t.kind === 'nudge');
const elsewhere = items.filter((t) => t.kind === 'elsewhere');
const waiting = items.filter((t) => t.kind === 'waiting');
const unanswered = items.filter((t) => t.kind === 'unanswered');
if (nudges.length) {
  lines.push('', ':envelope: *Reminder drafts ready in Gmail*');
  nudges.forEach((t) => lines.push('• ' + link(t) + ': no reply from ' + who(t) + ' for ' + plural(t.days)));
}
if (elsewhere.length) {
  lines.push('', ':inbox_tray: *They emailed you in another thread, so no reminder was drafted*');
  elsewhere.forEach((t) => lines.push('• ' + link(t) + ': ' + who(t) + ' wrote on ' + t.elsewhereOn + ' ("' + slackSafe(t.elsewhereSubject) + '"). Check whether it answers the review. ' +
    '<https://mail.google.com/mail/u/0/#all/' + t.elsewhereThreadId + '|Open it>'));
}
if (waiting.length) {
  lines.push('', ':hourglass: *Still waiting on the client*');
  waiting.forEach((t) => lines.push('• ' + link(t) + ': ' + who(t) + ', ' + plural(t.days) + ' since the last email' + (t.hasDraft ? ' (a reminder draft is already waiting in Gmail)' : '')));
}
if (unanswered.length) {
  lines.push('', ':speech_balloon: *Someone is waiting on you*');
  unanswered.forEach((t) => lines.push('• ' + link(t) + ': a reply came in ' + plural(t.days) + ' ago and has no answer yet'));
}
if (nudges.length) lines.push('', 'Nothing has been sent. Check the reminder drafts in Gmail and send the ones you want.');
return [{ json: { slackText: lines.join('\n') } }];

