// Check Claude's reading against the client's own words, then decide what happens to the task. Only a clear, unconditional approval moves it.
const cfg = $('Config').first().json;
const task = $('Loop Over Replies').first().json;
const raw = $input.first().json || {};
const ai = raw.output || {};
const text = String(task.replyText || '');

// 1. Compare words only: capital letters, punctuation and apostrophes do not matter
const norm = (s) => String(s || '').toLowerCase().replace(/[‘’ʼ`']/g, '').replace(/[^a-z0-9$£€%]+/g, ' ').trim();
const email = ' ' + norm(text) + ' ';
const sentences = text.split(/(?<=[.!?])\s+|\n+/).map(norm).filter(Boolean);
// A short quote such as "Approved" must be a whole sentence, so "Not approved" can never count as an approval
function inEmail(quote) {
  const q = norm(quote);
  if (!q) return false;
  if (q.split(' ').length < 3) return sentences.includes(q);
  return email.includes(' ' + q + ' ');
}
const phrases = String(cfg.approvalPhrases || '').split(',').map(norm).filter(Boolean);
const hasPhrase = (s) => phrases.some((p) => (' ' + norm(s) + ' ').includes(' ' + p + ' '));

// 2. Words that turn an approval into "a person should read this": a question, a request, a condition, a later check or a partial yes
const asksForSomething = /\?|\b(can|could|would|will) you\b|\bplease (change|make|swap|remove|add|fix|move|replace|update|cut|shorten|edit|send|tweak|adjust)\b|\binstead\b|\bbut\b|\bhowever\b/i;
const notFinal = new RegExp('\\b(so far|for now|at first glance|first look|quick look|initial|in principle|tentative(ly)?|almost|nearly|mostly|partly|partially|' +
  'not yet|pending|once (you|we|the|it)|as long as|provided|on condition|subject to|except|apart from|other than|' +
  'still (need|needs|waiting|to)|waiting (on|for)|(from|on) my (side|end)|for the most part|(one|1) (more |last |tiny |small |little |minor )?(thing|tweak|note|point|request|change)|' +
  'i think|i guess|i suppose|probably|maybe|perhaps|not sure|unsure|(will|ill|let me|need to|have to|has to|want to|going to|gonna) (check|confirm|review|look|run|discuss|ask|show|think|get back|come back|circle back|sign off)|' +
  'check with|confirm with|run (it|this) (by|past)|get back to you|come back to you|circle back|' +
  '(boss|manager|team|partner|client|board|director|ceo|founder|legal|colleague|cofounder)s? (needs to|will|has to|must|wants to|to) (see|sign|approve|review|check|confirm|look))\\b', 'i');
const negated = /\b(not|never|no longer|cannot|can t|cant|wont|won t|dont|don t|isnt|isn t)\b/;
// Words that usually mean the client wants something changed. Common harmless phrases are removed first, such as "no changes needed".
const calm = text.toLowerCase().replace(/[‘’ʼ`']/g, '')
  .replace(/\b(no|without any) (further |more |other )?(changes|edits|notes|tweaks|comments|feedback|revisions)( needed| required| from me| from us| from our side)?\b/g, ' ')
  .replace(/\b(nothing|not a thing) (else )?to (change|add|fix|edit)\b/g, ' ')
  .replace(/\b(dont|do not|wouldnt|would not|wont|will not) change (a thing|anything)\b/g, ' ')
  .replace(/\b(let (me|us) know )?if (you need|there is|theres) anything( else)?\b|\blet (me|us) know if\b|\b(move|moving) (forward|ahead)\b|\bthanks? (you )?for the update\b|\b(cant|can not|cannot) wait\b/g, ' ');
const changeWord = calm.match(/\b(change|changes|changed|edit|edits|tweak|tweaks|adjust|fix|swap|replace|remove|delete|add|move|update|revise|redo|rework|correct|typo|typos|mistake|wrong|missing|bigger|smaller|larger|shorter|longer|louder|quieter|brighter|darker|lighter|though|although|want|wants|wish|prefer|need|needs|should|must|rather|actually|wait|hold|unless|if|(would|wed|id)( also| really| just)? (love|like))\b/);
// Client text shown in our notes can never pretend to be one of the workflow's own markers
const safe = (s) => String(s || '').replace(/\(n8n review:/gi, '(n8n-review:');

const decision = String(ai.decision || 'unclear');
const changes = (Array.isArray(ai.changes) ? ai.changes : [])
  .map((c) => ({ change: String((c && c.change) || '').trim(), quote: String((c && c.quote) || '').trim() }))
  .filter((c) => c.quote);
const decisionQuote = String(ai.decision_quote || '').trim();
const question = String(ai.question || '').trim();

let outcome = 'check';
let problem = '';
if (!raw.output) {
  problem = 'Claude could not read this reply.';
} else if (decision === 'approved') {
  if (changes.length) problem = 'Claude said approved but also listed changes.';
  else if (asksForSomething.test(text)) problem = 'the reply also contains a question or a request';
  else if (notFinal.test(text.replace(/[‘’ʼ`']/g, ''))) problem = 'the approval sounds conditional, partial or not final yet';
  else if (changeWord) problem = 'it reads like an approval, but it also says "' + changeWord[1] + '", which can mean they want a change';
  else if (!inEmail(decisionQuote)) problem = 'the approval sentence Claude quoted is not in the email';
  else if (negated.test(norm(decisionQuote))) problem = 'the approval sentence contains a "not"';
  else if (!hasPhrase(decisionQuote)) problem = 'the reply does not use any of your approval phrases';
  else outcome = 'approved';
} else if (decision === 'changes_requested') {
  const notFound = changes.filter((c) => !inEmail(c.quote));
  if (!changes.length) problem = 'Claude said changes were requested but listed none';
  else if (notFound.length) problem = 'some of the changes Claude quoted are not in the email';
  else outcome = 'changes';
} else if (decision === 'question') {
  if (question && !inEmail(question)) problem = 'the question Claude quoted is not in the email';
  else outcome = 'question';
} else {
  problem = 'the reply does not approve the work, ask for changes or ask a question';
}

// 3. The words for the task note and Slack. The quotes shown are the client's own words, checked above.
const when = DateTime.fromMillis(Number(task.replyAt) || Date.now(), { zone: $now.zoneName }).toFormat('d LLL, HH:mm');
const ids = task.replyIds.join(' ');
const capital = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const slackSafe = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const taskLink = '<' + task.taskUrl + '|' + slackSafe(task.taskName) + '>';
const mailLink = '<https://mail.google.com/mail/u/0/#all/' + task.threadId + '|Open the email>';
const who = slackSafe(task.clientName || task.clientEmails.join(', '));
const quotes = changes.map((c) => '• "' + safe(c.quote) + '"').join('\n');
// The client's full reply goes on the task too, so nothing is lost if Claude missed a point
const fullReply = '\n\nTheir full reply:\n' + safe(text.length > 1500 ? text.slice(0, 1500) + ' [...]' : text);
const slackQuotes = changes.map((c) => '> "' + slackSafe(c.quote) + '"').join('\n');

let comment;
let slack;
let failComment = '';
let failSlack = '';
if (outcome === 'approved') {
  comment = '✅ The client approved this by email on ' + when + ':\n"' + safe(decisionQuote) + '"\n\nMoved to ' + cfg.approvedStatus + '.' + fullReply + '\n(n8n review: reply ' + ids + ', approved)';
  slack = ':white_check_mark: *' + who + ' approved* ' + taskLink + '\n> "' + slackSafe(decisionQuote) + '"\nMoved to ' + slackSafe(cfg.approvedStatus) + '. ' + mailLink;
  failComment = '✅ The client approved this by email on ' + when + ':\n"' + safe(decisionQuote) + '"\n\nClickUp would not move the task to "' + cfg.approvedStatus +
    '" ({error}). Check that this list has a status with that exact name, then move the task yourself.' + fullReply + '\n(n8n review: reply ' + ids + ', check)';
  failSlack = ':white_check_mark: *' + who + ' approved* ' + taskLink + '\n> "' + slackSafe(decisionQuote) + '"\n:warning: ClickUp would not move it to ' + slackSafe(cfg.approvedStatus) + ' ({error}). Move it yourself. ' + mailLink;
} else if (outcome === 'changes') {
  comment = '✏️ The client asked for changes by email on ' + when + ':\n' + quotes + '\n\nMoved to ' + cfg.changesStatus + ' and added them as a checklist.' + fullReply + '\n(n8n review: reply ' + ids + ', changes)';
  slack = ':pencil2: *' + who + ' asked for ' + changes.length + (changes.length === 1 ? ' change' : ' changes') + '* on ' + taskLink + '\n' + slackQuotes +
    '\nMoved to ' + slackSafe(cfg.changesStatus) + ', with a checklist on the task. ' + mailLink;
  failComment = '✏️ The client asked for changes by email on ' + when + ':\n' + quotes + '\n\nClickUp would not move the task to "' + cfg.changesStatus +
    '" ({error}). Check that this list has a status with that exact name, then move the task yourself.' + fullReply + '\n(n8n review: reply ' + ids + ', check)';
  failSlack = ':pencil2: *' + who + ' asked for changes* on ' + taskLink + '\n' + slackQuotes + '\n:warning: ClickUp would not move it to ' + slackSafe(cfg.changesStatus) + ' ({error}). Move it yourself. ' + mailLink;
} else if (outcome === 'question') {
  const q = question || decisionQuote;
  comment = '❓ The client replied with a question on ' + when + (q ? ':\n"' + safe(q) + '"' : '.') + '\n\nThe task stays in ' + cfg.reviewStatus + '. Answer them in Gmail.' + fullReply + '\n(n8n review: reply ' + ids + ', question)';
  slack = ':question: *' + who + ' has a question* about ' + taskLink + (q ? '\n> "' + slackSafe(q) + '"' : '') + '\nNothing was changed. Answer them in the same email thread. ' + mailLink;
} else {
  comment = '⚠️ The client replied on ' + when + ', but the workflow did not act on it (' + safe(problem).replace(/\.$/, '') + '). Nothing was changed. Read it in Gmail.' + fullReply + '\n(n8n review: reply ' + ids + ', check)';
  slack = ':warning: *' + who + ' replied* about ' + taskLink + ', but nothing was changed (' + slackSafe(problem.replace(/\.$/, '').toLowerCase()) + '). Please read it yourself. ' + mailLink;
}

return [{
  json: {
    outcome,
    problem,
    summary: String(ai.summary || ''),
    checklistName: 'Client changes, ' + DateTime.fromMillis(Number(task.replyAt) || Date.now(), { zone: $now.zoneName }).toFormat('d LLL'),
    checklistItems: changes.map((c) => capital(c.quote).slice(0, 250)),
    comment,
    slackText: slack,
    failComment,
    failSlack
  }
}];

// Use the note from Check Reply Against Email, or explain that ClickUp would not move the task (the round then stays open)
const base = $('Check Reply Against Email').first().json;
let comment = base.comment;
let slackText = base.slackText;
const moveNode = base.outcome === 'approved' ? 'Move Task to Approved' : base.outcome === 'changes' ? 'Move Task to Changes Status' : '';
if (moveNode) {
  const moved = $(moveNode).first();
  const res = (moved && moved.json) || {};
  if (!res.id) {
    const err = (moved && moved.error) || res.error || res.err || 'no answer from ClickUp';
    const reason = String((err && err.message) || err).replace(/[()]/g, '').slice(0, 200);
    comment = base.failComment.replace('{error}', reason);
    slackText = base.failSlack.replace('{error}', reason);
  }
}
if (base.outcome === 'changes') {
  const list = $('Create Changes Checklist').first();
  if (!list || !list.json || !(list.json.id || (list.json.checklist && list.json.checklist.id))) {
    comment = comment.replace('and added them as a checklist', 'but the checklist could not be created, so the changes are listed here');
    slackText = slackText.replace(', with a checklist on the task', '. The checklist could not be created, so the changes are in the task note');
  }
}
return [{ json: { comment, slackText } }];

// One item per change the client asked for, each going into the new checklist (nothing if ClickUp did not create the checklist)
const created = $input.first().json || {};
const checklistId = created.id || (created.checklist && created.checklist.id);
if (!checklistId) return [];
return $('Check Reply Against Email').first().json.checklistItems.map((name) => ({ json: { checklistId, name } }));

// Tasks that still carry the waiting tag but have left the review status: their review round is over, so the tag comes off
if ($('Every Morning at 9').isExecuted) return [];
const cfg = $('Config').first().json;
const pages = $input.all().map((i) => i.json || {});
const failed = pages.find((p) => p.err || p.ECODE);
if (failed) {
  throw new Error('ClickUp said: ' + (failed.err || failed.ECODE) + ' while looking for tasks with the "' + cfg.waitingTag + '" tag.');
}
const lower = (v) => String(v == null ? '' : v).trim().toLowerCase();
const review = lower(cfg.reviewStatus);
const tag = lower(cfg.waitingTag);
const seen = new Set();
return pages
  .flatMap((p) => (Array.isArray(p.tasks) ? p.tasks : []))
  .filter((t) => t && t.id && !seen.has(t.id) && seen.add(t.id))
  .filter((t) => (t.tags || []).some((g) => lower(g && g.name) === tag))
  .filter((t) => lower(t.status && t.status.status) !== review)
  .map((t) => ({ json: { taskId: t.id, taskName: t.name } }));
